package com.estoqueinteligente.product;
import java.math.BigDecimal;import java.time.*;import com.estoqueinteligente.category.Category;import com.estoqueinteligente.supplier.Supplier;import jakarta.persistence.*;
@Entity @Table(name="products")public class Product{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=150)private String name;@Column(unique=true,length=50)private String barcode;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="category_id")private Category category;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="supplier_id")private Supplier supplier;@Column(name="cost_price",nullable=false,precision=12,scale=2)private BigDecimal costPrice;@Column(name="sale_price",nullable=false,precision=12,scale=2)private BigDecimal salePrice;@Column(nullable=false)private Integer quantity;@Column(name="minimum_stock",nullable=false)private Integer minimumStock;@Column(name="expiration_date")private LocalDate expirationDate;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ProductStatus status;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@PrePersist void createTimestamps(){createdAt=updatedAt=Instant.now();}@PreUpdate void updateTimestamp(){updatedAt=Instant.now();}public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getBarcode(){return barcode;}public void setBarcode(String v){barcode=v;}public Category getCategory(){return category;}public void setCategory(Category v){category=v;}public Supplier getSupplier(){return supplier;}public void setSupplier(Supplier v){supplier=v;}public BigDecimal getCostPrice(){return costPrice;}public void setCostPrice(BigDecimal v){costPrice=v;}public BigDecimal getSalePrice(){return salePrice;}public void setSalePrice(BigDecimal v){salePrice=v;}public Integer getQuantity(){return quantity;}public void setQuantity(Integer v){quantity=v;}public Integer getMinimumStock(){return minimumStock;}public void setMinimumStock(Integer v){minimumStock=v;}public LocalDate getExpirationDate(){return expirationDate;}public void setExpirationDate(LocalDate v){expirationDate=v;}public ProductStatus getStatus(){return status;}public void setStatus(ProductStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
